WITH frontier AS (SELECT f.dbid, f.classid, f.objid, f.objsubid FROM ROWS FROM (pg_catalog.unnest($1::pg_catalog.oid[]) , pg_catalog.unnest($2::pg_catalog.oid[]) , pg_catalog.unnest($3::pg_catalog.oid[]) , pg_catalog.unnest($4::int[]) ) f(dbid, classid, objid, objsubid)) SELECT d.dbid::text AS dependent_database_oid, d.classid::text AS dependent_class_oid, d.objid::text AS dependent_object_oid, d.objsubid::text AS dependent_subobject, d.refclassid::text AS referenced_shared_class_oid, d.refobjid::text AS referenced_shared_object_oid, d.deptype::text AS dependency_kind, pg_catalog.to_jsonb(d)::pg_catalog.text AS original_catalog_row_json FROM pg_catalog.pg_shdepend d WHERE EXISTS (SELECT 1 FROM frontier f WHERE f.dbid = d.dbid AND f.classid = d.classid AND f.objid = d.objid AND f.objsubid = d.objsubid) ORDER BY d.dbid, d.classid, d.objid, d.objsubid, d.refclassid, d.refobjid, d.deptype